 * Fetch and show calendars and address books for the account.
 */
async #fetchSyncAccounts() {
  try {
    this.#startLoading("account-hub-finding-sync-accounts");

    this.abortable = new AbortController();
    this.#emailFooter.setDirectionalButtonText(
      "back",
      "account-hub-email-skip-button"
    );

    // We'll look for address books and calendars at the domain of the email
    // address, the incoming mail server's hostname, and, if it's different
    // but is at the same site according to the eTLD service, the domain of
    // the incoming mail server.
    const hostnames = [this.#email.split("@")[1]];
    const incomingHostname = this.#currentConfig.incoming.hostname;
    if (
      incomingHostname != hostnames[0] &&
      Services.eTLD.getSchemelessSiteFromHost(incomingHostname) ==
        Services.eTLD.getSchemelessSiteFromHost(hostnames[0])
    ) {
      hostnames.push(incomingHostname);
    }

    // If this is a graph email server, then we want to pass the incoming
    // server's hostname in for calendar discovery as well.
    if (this.#currentConfig.incoming.type === "graph") {
      hostnames.push(incomingHostname);
    }

    gAccountSetupLogger.debug(
      `Discovering address books and calendars at ${hostnames.join(", ")}.`
    );

    const syncAccounts = {};
    // TODO: fetch address books and calendars in parallel?
    syncAccounts.addressBooks = await this.#getAddressBooks(
      hostnames,
      this.#currentConfig.incoming.password ?? ""
    );

    // If the user hit cancel while loading, we won't fetch
    // the calendars and a UserSkippedError will be thrown.
    this.abortable.signal.throwIfAborted();

    // Add a 1 second delay here to give the users a chance to skip this
    // altogether.
    await abortableTimeout(1000, this.abortable.signal);

    syncAccounts.calendars = await this.#getCalendars(
      hostnames,
      this.#currentConfig.incoming.password ?? "",
      this.#currentConfig.rememberPassword ?? false
    );

    // If the user hit cancel while loading, a UserSkippedError will be
    // thrown.
    this.abortable?.signal?.throwIfAborted();
